CREATE TABLE IF NOT EXISTS boards (id INTEGER PRIMARY KEY, roster_id INTEGER, game TEXT, map TEXT, title TEXT, state TEXT, updated_at INTEGER, updated_by TEXT);
CREATE TABLE IF NOT EXISTS competitions (id INTEGER PRIMARY KEY, roster_id INTEGER, name TEXT, organizer TEXT, url TEXT, level TEXT,
  signup_by INTEGER, starts INTEGER, status TEXT DEFAULT 'repere', result TEXT, note TEXT, created_by TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS contacts (id INTEGER PRIMARY KEY, type TEXT, name TEXT, reply TEXT, message TEXT, at INTEGER, ip TEXT, message_id TEXT, status TEXT DEFAULT 'nouveau');
CREATE TABLE IF NOT EXISTS content_tasks (id INTEGER PRIMARY KEY, match_id INTEGER, kind TEXT, title TEXT, brief TEXT, networks TEXT,
    due INTEGER, assignee TEXT, status TEXT DEFAULT 'a-faire', url TEXT, created_by TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS creators (user_id TEXT PRIMARY KEY, twitch TEXT, youtube TEXT);
CREATE TABLE IF NOT EXISTS dispo_days (roster_id INTEGER, week TEXT, user_id TEXT, day INTEGER, state TEXT, start TEXT, PRIMARY KEY (roster_id, week, user_id, day));
CREATE TABLE IF NOT EXISTS dispo_type (roster_id INTEGER, user_id TEXT, data TEXT, PRIMARY KEY (roster_id, user_id));
CREATE TABLE IF NOT EXISTS docs (id INTEGER PRIMARY KEY, roster_id INTEGER, title TEXT, body TEXT, pinned INTEGER DEFAULT 0, author TEXT, updated_at INTEGER);
