CREATE TABLE IF NOT EXISTS goals (id INTEGER PRIMARY KEY, roster_id INTEGER, user_id TEXT, title TEXT, detail TEXT, due INTEGER, status TEXT DEFAULT 'en-cours', progress INTEGER DEFAULT 0, created_by TEXT, at INTEGER, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS guild_members (id TEXT PRIMARY KEY, name TEXT, avatar TEXT, roles TEXT, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS guild_roles (id TEXT PRIMARY KEY, name TEXT, color INTEGER, position INTEGER, admin INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS inhouse_elo (user_id TEXT, mode TEXT, season INTEGER, rating INTEGER DEFAULT 1000, wins INTEGER DEFAULT 0, losses INTEGER DEFAULT 0, streak INTEGER DEFAULT 0, best INTEGER DEFAULT 1000, PRIMARY KEY (user_id, mode, season));
