CREATE TABLE IF NOT EXISTS match_notes (match_id INTEGER, user_id TEXT, good TEXT, work TEXT, rating INTEGER, at INTEGER, PRIMARY KEY (match_id, user_id));
CREATE TABLE IF NOT EXISTS match_replays (match_id INTEGER, replay TEXT, status TEXT DEFAULT 'attente', at INTEGER, PRIMARY KEY (match_id, replay));
CREATE TABLE IF NOT EXISTS match_stats (match_id INTEGER, user_id TEXT, data TEXT, at INTEGER, PRIMARY KEY (match_id, user_id));
CREATE TABLE IF NOT EXISTS matches (id INTEGER PRIMARY KEY, game TEXT, roster_id INTEGER, opponent TEXT, format TEXT, at INTEGER, link TEXT,
