CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS metrics (day TEXT, key TEXT, value REAL, source TEXT, PRIMARY KEY (day, key));
CREATE TABLE IF NOT EXISTS opponents (id INTEGER PRIMARY KEY, roster_id INTEGER, name TEXT, players TEXT, style TEXT, forces TEXT, faiblesses TEXT, plan TEXT, links TEXT, author TEXT, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS osu_maps (id INTEGER PRIMARY KEY, roster_id INTEGER, beatmap_id INTEGER, note TEXT, challenge INTEGER DEFAULT 0, ends INTEGER, meta TEXT, added_by TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS perf (id TEXT PRIMARY KEY, user_id TEXT, game TEXT, at INTEGER, data TEXT);
CREATE TABLE IF NOT EXISTS rank_history (user_id TEXT, game TEXT, day TEXT, value TEXT, PRIMARY KEY (user_id, game, day));
CREATE TABLE IF NOT EXISTS rl_sync (user_id TEXT PRIMARY KEY, token TEXT UNIQUE, created_at INTEGER, last_at INTEGER, last_error TEXT);
CREATE TABLE IF NOT EXISTS roster_postes (roster_id INTEGER, user_id TEXT, poste TEXT, PRIMARY KEY (roster_id, user_id));
