CREATE TABLE IF NOT EXISTS setups (user_id TEXT, game TEXT, data TEXT, updated_at INTEGER, PRIMARY KEY (user_id, game));
CREATE TABLE IF NOT EXISTS staff_public (user_id TEXT PRIMARY KEY, visible INTEGER DEFAULT 0, bio TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS stats_cache (key TEXT PRIMARY KEY, value TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS survey_answers (campaign TEXT, user_id TEXT, answers TEXT, at INTEGER, PRIMARY KEY (campaign, user_id));
CREATE TABLE IF NOT EXISTS temp_voices (channel_id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS tickets (thread_id TEXT PRIMARY KEY, user_id TEXT, kind TEXT, game TEXT, opened_at INTEGER, closed_at INTEGER);
CREATE TABLE IF NOT EXISTS trainings (id INTEGER PRIMARY KEY, roster_id INTEGER, at INTEGER, duration INTEGER, kind TEXT, note TEXT,
      message_id TEXT, reminded INTEGER DEFAULT 0, cancelled INTEGER DEFAULT 0, created_by TEXT);
CREATE TABLE IF NOT EXISTS vod_marks (id INTEGER PRIMARY KEY, vod_id INTEGER, t INTEGER, text TEXT, kind TEXT, author TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS vods (id INTEGER PRIMARY KEY, roster_id INTEGER, title TEXT, url TEXT, match_id INTEGER, added_by TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS warnings (id INTEGER PRIMARY KEY, user_id TEXT, mod_id TEXT, reason TEXT, at INTEGER);
